arguments.command:
cat > tests/overdue_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/overdue 10 8)" = "on time" ] || { echo "overdue 10 8"; fail=1; }
[ "$(bash bin/overdue 10 10)" = "on time" ] || { echo "overdue 10 10"; fail=1; }
[ "$(bash bin/overdue 10 13)" = "overdue 3 days" ] || { echo "overdue 10 13"; fail=1; }
exit $fail
EOF
git stash -q -- bin/overdue; bash scripts/verify.sh; echo "pre-fix rc=$?"; git stash pop -q
bash scripts/verify.sh; echo "post-fix rc=$?"

